class ModelRegistry:
    """Persistent registry with atomic JSON writes."""

    def __init__(self, path: str | Path) -> None:
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)

        self._models: dict[str, ModelRecord] = {}
        self._lock = Lock()

        self.load()

    @staticmethod
    def key(provider: str, model_id: str) -> str:
        return f"{provider.lower()}:{model_id}"

    def load(self) -> None:
        if not self.path.exists():
            return

        try:
            data = json.loads(
                self.path.read_text(encoding="utf-8")
            )

            models = data.get("models", {})

            for key, raw in models.items():
                self._models[key] = ModelRecord(**raw)

        except Exception:
            self._models = {}

    def save(self) -> None:
        with self._lock:
            payload = {
                "schema_version": 1,
                "generated_at": time.time(),
                "models": {
                    key: asdict(record)
                    for key, record in self._models.items()
                },
            }

            self.path.parent.mkdir(parents=True, exist_ok=True)

            fd, temporary = tempfile.mkstemp(
                prefix=".registry_",
                suffix=".tmp",
                dir=self.path.parent,
                text=True,
            )

            try:
                with os.fdopen(fd, "w", encoding="utf-8") as handle:
                    json.dump(
                        payload,
                        handle,
                        ensure_ascii=False,
                        indent=2,
                        sort_keys=True,
                    )
                    handle.flush()
                    os.fsync(handle.fileno())

                os.replace(temporary, self.path)

            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)

    def upsert(self, record: ModelRecord) -> None:
        with self._lock:
            self._models[
                self.key(record.provider, record.model_id)
            ] = record

    def get(
        self,
        provider: str,
        model_id: str,
    ) -> ModelRecord | None:
        return self._models.get(
            self.key(provider, model_id)
        )



    def all(self) -> list[ModelRecord]:
        with self._lock:
            return list(self._models.values())

    def active(self) -> list[ModelRecord]:
        with self._lock:
            return [
                record
                for record in self._models.values()
                if str(getattr(record, "lifecycle", "")).upper() == "ACTIVE"
            ]

